descriptor.templateCss:
.bess-rack-card {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #64B856;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.bess-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.card-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.card-icon { font-size: 16px; }
.badge-status {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
}
.badge-status.ok {
  color: #64B856;
  border: 1.5px solid #64B856;
  background: rgba(100, 184, 86, 0.1);
}
.badge-status.warn {
  color: #f59e0b;
  border: 1.5px solid #f59e0b;
  background: rgba(245, 158, 11, 0.1);
}
.racks-container {
  display: flex;
  justify-content: space-around;
  align-items: flex-end;
  padding: 6px 10px;
}
.rack-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}
.rack-meter {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.meter-cap {
  width: 14px;
  height: 4px;
  background: rgba(255, 255, 255, 0.25);
  border-radius: 2px 2px 0 0;
}
.meter-body {
  width: 42px;
  height: 68px;
  background: rgba(255, 255, 255, 0.04);
  border: 1.5px solid rgba(255, 255, 255, 0.15);
  border-radius: 5px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  overflow: hidden;
}
.meter-fill {
  width: 100%;
  background: linear-gradient(180deg, #64B856 0%, #059669 100%);
  border-radius: 0 0 3px 3px;
  transition: height 0.5s ease, background 0.3s ease;
}
.meter-ticks {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  pointer-events: none;
}
.meter-ticks span {
  display: block;
  width: 100%;
  height: 1px;
  background: rgba(255, 255, 255, 0.12);
}
.rack-val {
  font-size: 15px;
  font-weight: 800;
  color: #f1f5f9;
}
.rack-lbl {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
}
.bess-card-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 8px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() { self.onDataUpdated(); };
self.onDataUpdated = function() {
  var data = self.ctx.data;
  var s1 = 86, s2 = 85, s3 = 87;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var v = parseFloat(item.data[item.data.length - 1][1]);
        var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        if (!isNaN(v)) {
          if (k.indexOf('pcs1') !== -1 || i === 0) s1 = v;
          else if (k.indexOf('pcs2') !== -1 || i === 1) s2 = v;
          else if (k.indexOf('pcs3') !== -1 || i === 2) s3 = v;
        }
      }
    }
  }

  var avg = (s1 + s2 + s3) / 3;
  var delta = Math.max(s1, s2, s3) - Math.min(s1, s2, s3);
  var container = self.ctx.$container ? self.ctx.$container[0] : null;

  if (container) {
    var updateRack = function(idVal, idFill, val) {
      var ev = container.querySelector(idVal);
      var ef = container.querySelector(idFill);
      if (ev) ev.textContent = Math.round(val) + '%';
      if (ef) {
        ef.style.height = Math.min(100, Math.max(0, val)) + '%';
        if (val < 20) ef.style.background = '#ef4444';
        else if (val < 40) ef.style.background = '#f59e0b';
        else ef.style.background = 'linear-gradient(180deg, #64B856 0%, #059669 100%)';
      }
    };
    updateRack('#rack1-soc-val', '#rack1-fill', s1);
    updateRack('#rack2-soc-val', '#rack2-fill', s2);
    updateRack('#rack3-soc-val', '#rack3-fill', s3);

    var elAvg = container.querySelector('#soc-avg-val');
    if (elAvg) elAvg.textContent = avg.toFixed(1) + '%';

    var elBadge = container.querySelector('#soc-dispersion-badge');
    if (elBadge) {
      var isOk = delta <= 3.0;
      elBadge.textContent = isOk ? 'EQUILIBRADO (Δ ' + delta.toFixed(1) + '%)' : 'DESBALANCE (Δ ' + delta.toFixed(1) + '%)';
      elBadge.className = 'badge-status ' + (isOk ? 'ok' : 'warn');
    }
  }
};
self.onDestroy = function() {};
